-- Retires the old habit-style Mindfulness calendar and adds the 24-door Hiking Adventures calendar.
-- Existing activity, completion, points, and redemption rows are preserved.
-- Safe to run more than once.
BEGIN;
UPDATE calendars SET status = 'inactive' WHERE category = 'Mindfulness/Self-Help' OR title = 'Mindfulness & Self-Help';
UPDATE calendars SET status = 'active' WHERE title = 'Hiking Adventures' AND category = 'Hiking';
UPDATE calendars SET start_date = CURRENT_DATE - 11 WHERE title = 'Hiking Adventures' AND category = 'Hiking' AND start_date IS NULL;
UPDATE group_sessions SET status = 'closed' WHERE status IN ('open', 'full') AND activity_id IN (SELECT a.id FROM activities a JOIN calendars c ON c.id = a.calendar_id WHERE c.category = 'Mindfulness/Self-Help' OR c.title = 'Mindfulness & Self-Help');
COMMIT;
