INSERT INTO calendars (title, category, description, icon, tier_required, status, start_date) SELECT 'Hiking Adventures', 'Hiking', 'Twenty-four outdoor mini-adventures: discover local trails, viewpoints, forests and hidden green spaces at your own pace.', 'ph-mountains', 'free', 'active', CURRENT_DATE - 11 WHERE NOT EXISTS (SELECT 1 FROM calendars WHERE title = 'Hiking Adventures' AND category = 'Hiking');
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Pick Your Trail', 'Every great outing starts with a route that makes you curious.', 'Choose a nearby marked trail, waterfront path or greenway. Check distance, opening hours and the forecast, and save an easier alternative.', 1, 20, '10 mins', 'ph-map-trifold', 'free', TRUE FROM calendars c WHERE c.title = 'Hiking Adventures' AND c.category = 'Hiking' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'The Scenic Detour', 'A small change of route can reveal a place you have never noticed.', 'Take a familiar, safe route and add one marked side path or viewpoint. Stay on public paths and turn back whenever you like.', 2, 20, '20 mins', 'ph-signpost', 'free', FALSE FROM calendars c WHERE c.title = 'Hiking Adventures' AND c.category = 'Hiking' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Waterfront Wander', 'Following the water makes an ordinary walk feel like an expedition.', 'Find a public riverside, lake or seafront trail. Walk at an easy pace, check local access notices and enjoy the views.', 3, 20, '30 mins', 'ph-waves', 'free', TRUE FROM calendars c WHERE c.title = 'Hiking Adventures' AND c.category = 'Hiking' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Forest Sound Safari', 'Listening closely turns the trail into a nature discovery game.', 'On a safe woodland path, pause three times and identify five different natural sounds. Keep a respectful distance from wildlife.', 4, 20, '25 mins', 'ph-tree-evergreen', 'free', FALSE FROM calendars c WHERE c.title = 'Hiking Adventures' AND c.category = 'Hiking' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Summit or Viewpoint Mission', 'A destination gives your hike a satisfying sense of adventure.', 'Choose a marked route to a viewpoint that fits your ability and daylight. Bring water, check the weather and skip exposed routes in poor conditions.', 5, 20, '45 mins', 'ph-mountains', 'free', TRUE FROM calendars c WHERE c.title = 'Hiking Adventures' AND c.category = 'Hiking' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Photo Scavenger Hike', 'A playful photo mission helps you notice details along the way.', 'On an easy public trail, photograph a leaf shape, an interesting texture, a wide view and a trail marker. Do not leave the path for a shot.', 6, 30, '30 mins', 'ph-camera', 'free', FALSE FROM calendars c WHERE c.title = 'Hiking Adventures' AND c.category = 'Hiking' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Wildflower Spotting', 'Seasonal colour makes the same trail feel different every time.', 'Look for three different wildflowers from the path. Use a local guide or app if you like; do not pick plants or enter protected areas.', 7, 20, '25 mins', 'ph-flower', 'free', TRUE FROM calendars c WHERE c.title = 'Hiking Adventures' AND c.category = 'Hiking' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Sunrise Trail Adventure', 'Early light can make a familiar landscape feel brand new.', 'Only if the route is open and conditions are safe, visit a nearby easy trail around sunrise. Tell someone your plan, bring a light and turn back if visibility is poor.', 8, 20, '35 mins', 'ph-sun-horizon', 'free', FALSE FROM calendars c WHERE c.title = 'Hiking Adventures' AND c.category = 'Hiking' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Park-to-Park Explorer', 'Connecting green spaces makes a city feel full of hidden trails.', 'Plan a walk between two public parks using sidewalks and marked paths. Choose a route with a simple shortcut back to your starting point.', 9, 20, '35 mins', 'ph-park', 'free', TRUE FROM calendars c WHERE c.title = 'Hiking Adventures' AND c.category = 'Hiking' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Creekside Discovery', 'A small stream offers plenty of details to discover at a gentle pace.', 'Follow a marked path beside a creek or canal. Stay on the trail, keep away from slippery banks and notice how the landscape changes.', 10, 20, '30 mins', 'ph-drop', 'free', FALSE FROM calendars c WHERE c.title = 'Hiking Adventures' AND c.category = 'Hiking' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Trail Map Challenge', 'Using a map adds a little expedition feeling to your outing.', 'Pick a short, well-marked loop and follow a downloaded map. Check your location at trail junctions; do not rely on mobile signal alone.', 11, 20, '30 mins', 'ph-compass', 'free', TRUE FROM calendars c WHERE c.title = 'Hiking Adventures' AND c.category = 'Hiking' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Leave No Trace Hike', 'Caring for a trail helps keep it beautiful for the next explorer.', 'Bring a small bag and pick up litter only when it is safe to do so. Leave plants, rocks and wildlife where they are, and follow local disposal rules.', 12, 30, '30 mins', 'ph-leaf', 'free', FALSE FROM calendars c WHERE c.title = 'Hiking Adventures' AND c.category = 'Hiking' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Golden Hour Loop', 'Warm evening light makes a simple loop feel like a special outing.', 'Choose an easy loop with enough daylight to finish comfortably. Check sunset time, bring a charged phone and head back early if the weather changes.', 13, 20, '30 mins', 'ph-sun', 'free', TRUE FROM calendars c WHERE c.title = 'Hiking Adventures' AND c.category = 'Hiking' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Hill Repeats, Your Pace', 'A gentle climb can turn a local hill into a mini adventure.', 'Choose a short, safe slope on a public path. Walk up once, rest, and repeat only if comfortable. Skip steep or slippery ground and take the easy route down.', 14, 20, '25 mins', 'ph-trend-up', 'free', FALSE FROM calendars c WHERE c.title = 'Hiking Adventures' AND c.category = 'Hiking' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Find a Hidden Garden', 'Small gardens and green corners can be surprising trail destinations.', 'Find a public garden, arboretum or community green space. Check opening times and explore its marked paths at your own pace.', 15, 20, '30 mins', 'ph-tree', 'free', TRUE FROM calendars c WHERE c.title = 'Hiking Adventures' AND c.category = 'Hiking' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Cloudscape Viewpoint', 'Looking up gives even a short walk a fresh perspective.', 'Walk to a safe open viewpoint or park bench. Notice three cloud shapes and how the light shifts; avoid exposed high ground during storms.', 16, 20, '25 mins', 'ph-cloud-sun', 'free', FALSE FROM calendars c WHERE c.title = 'Hiking Adventures' AND c.category = 'Hiking' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Choose-your-own Loop', 'A route you design yourself feels like your own little expedition.', 'Connect two or three marked paths into a loop suited to your time and ability. Save the map offline and share your route with someone.', 17, 20, '40 mins', 'ph-path', 'free', TRUE FROM calendars c WHERE c.title = 'Hiking Adventures' AND c.category = 'Hiking' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Bridge-to-Bridge Trek', 'Landmarks turn a trail into a point-to-point discovery.', 'Find a safe public path between two bridges or trail landmarks. Use crossings and walkways only; do not enter roadways or restricted areas.', 18, 30, '35 mins', 'ph-bridge', 'free', FALSE FROM calendars c WHERE c.title = 'Hiking Adventures' AND c.category = 'Hiking' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Nature Journal Walk', 'A few notes make small discoveries memorable without turning them into a task.', 'Bring a pocket notebook on an easy trail. Sketch or jot down one surprising thing you noticed, then put the notebook away and enjoy the rest.', 19, 20, '25 mins', 'ph-notebook', 'free', TRUE FROM calendars c WHERE c.title = 'Hiking Adventures' AND c.category = 'Hiking' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Choose a New Trailhead', 'Starting somewhere new is an easy way to make a local adventure feel fresh.', 'Use a local parks or trails directory to pick a public trailhead you have not visited. Check transport, parking, access and route difficulty first.', 20, 20, '40 mins', 'ph-map-pin', 'free', FALSE FROM calendars c WHERE c.title = 'Hiking Adventures' AND c.category = 'Hiking' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Wildlife-Watching Walk', 'Quiet observation can reveal birds and other wildlife along the trail.', 'Bring binoculars if you have them and stay quietly on a marked path. Observe from a distance, never feed or approach animals.', 21, 20, '30 mins', 'ph-binoculars', 'free', TRUE FROM calendars c WHERE c.title = 'Hiking Adventures' AND c.category = 'Hiking' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Rain-or-Shine Nature Quest', 'A light change in weather can make familiar scenery feel completely different.', 'If local advisories allow, take a short, sheltered public path with weather-appropriate layers. Avoid storms, flooding, icy routes and exposed terrain; an indoor nature-map quest is a fine alternative.', 22, 20, '20 mins', 'ph-umbrella', 'free', FALSE FROM calendars c WHERE c.title = 'Hiking Adventures' AND c.category = 'Hiking' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Pack a Trail Picnic', 'A snack stop turns a hike into a mini day out.', 'Choose a short route with a permitted rest spot. Pack water and a snack, check local food and fire rules, and carry every wrapper back out.', 23, 20, '40 mins', 'ph-basket', 'free', TRUE FROM calendars c WHERE c.title = 'Hiking Adventures' AND c.category = 'Hiking' ON CONFLICT (calendar_id, day_number) DO NOTHING;
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) SELECT c.id, 'Your Grand Finale: Favourite View', 'Finish the calendar by revisiting the moment or place you most enjoyed.', 'Choose a safe marked route to your favourite viewpoint from this calendar, or pick a new easy trail. Take a photo, celebrate the adventure and plan another outing only if it sounds fun.', 24, 30, '45 mins', 'ph-flag-checkered', 'free', FALSE FROM calendars c WHERE c.title = 'Hiking Adventures' AND c.category = 'Hiking' ON CONFLICT (calendar_id, day_number) DO NOTHING;
